</div></form><?php endif ?>
<?php if($record):?><div class="destination-admin-actions"><form method="post"><input type="hidden" name="csrf" value="<?=esc($_SESSION['csrf'])?>"><input type="hidden" name="id" value="<?=esc($id)?>"><input type="hidden" name="action" value="archive"><button class="pill light" onclick="return confirm('¿Archivar este destino? Sus negocios y relaciones se conservarán.')">Archivar destino</button></form><form method="post"><input type="hidden" name="csrf" value="<?=esc($_SESSION['csrf'])?>"><input type="hidden" name="id" value="<?=esc($id)?>"><input type="hidden" name="action" value="delete"><button class="pill danger" onclick="return confirm('¿Borrar definitivamente este destino y sus contenidos? Esta acción no se puede deshacer.')">Borrar definitivamente</button></form></div><?php endif ?>
<?php if($record):?><p class="destination-preview-link"><a class="pill light" href="../destinos/<?=esc($record['slug'])?>/?preview=1" target="_blank" rel="noopener">Abrir vista previa privada ↗</a><small>Solo tú podrás verla mientras sigas autenticado; Google no la indexará.</small></p><?php endif ?>
<script>
(()=>{
 const form=document.querySelector('.destination-editor'),container=document.querySelector('.destination-editor fieldset:nth-of-type(2)'),template=document.getElementById('destination-place-template'),add=document.getElementById('add-destination-place'),file=document.getElementById('destination-package-file'),status=document.getElementById('destination-import-status');
 if(!form||!container||!template||!add||!file)return;
 const rows=()=>[...container.querySelectorAll('[data-place-row]')];
 function addRow(){const index=rows().length;const holder=document.createElement('div');holder.innerHTML=template.innerHTML.replace(/places\[0\]/g,`places[${index}]`);const row=holder.firstElementChild;row.querySelector('summary').textContent=`Atractivo ${index+1}`;row.querySelectorAll('input:not([type=hidden]),textarea').forEach(el=>{if(el.type!=='file')el.value='';});row.querySelectorAll('input[type=hidden]').forEach(el=>el.value='');container.insertBefore(row,add);return row;}
 add.addEventListener('click',()=>{if(rows().length>=40){status.textContent='Un destino admite hasta 40 atractivos.';return;}addRow().open=true;});
 const publication=form.elements.namedItem('publication_status'),saveButton=form.querySelector('button[type="submit"]');
 if(publication&&saveButton){const updateSaveLabel=()=>saveButton.textContent=publication.value==='published'?'Guardar y publicar':(publication.value==='archived'?'Guardar y retirar del sitio':'Guardar como borrador');publication.addEventListener('change',updateSaveLabel);updateSaveLabel();form.addEventListener('submit',event=>{if(publication.value==='published'&&!confirm('Esto publicará el destino y sus atractivos aprobados para los visitantes. ¿Continuar?'))event.preventDefault();});const publishButton=form.querySelector('#publish-destination');if(publishButton)publishButton.addEventListener('click',()=>{publication.value='published';updateSaveLabel();form.requestSubmit(saveButton);});}
 const legacyFile=document.getElementById('destination-legacy-json-file');
 const tokenInput=form.elements.namedItem('package_import_token');
 const preview=document.getElementById('destination-package-preview');
 const set=(name,value)=>{const el=form.elements.namedItem(name);if(el&&(typeof value==='string'||typeof value==='number'))el.value=String(value);};
 const list=(v)=>Array.isArray(v)?v.join('\n'):(typeof v==='string'?v:'');
 const imageInputs=()=>[...form.querySelectorAll('input[type="file"]')];
 const clearPreviews=()=>{preview.querySelectorAll('img[data-object-url]').forEach(img=>URL.revokeObjectURL(img.dataset.objectUrl));preview.replaceChildren();};
 function loadTextPackage(pack, keepImageFiles=false){
  const d=pack.destination,translations=d.translations||{};set('slug',d.slug||'');set('destination_type',d.destination_type||'municipality');set('country_code',d.country_code||'CO');set('department',d.department||'');set('subregion',d.subregion||'');set('latitude',d.latitude??'');set('longitude',d.longitude??'');
  for(const locale of ['es','en','pt-BR']){const t=translations[locale]||{};for(const key of ['display_name','eyebrow','headline','intro','meta_description'])set(`translations[${locale}][${key}]`,t[key]||'');set(`history[${locale}]`,list((d.history||{})[locale]));set(`reasons[${locale}]`,list((d.reasons||{})[locale]));const sources=((d.sources||{})[locale]||[]).map(s=>typeof s==='string'?s:`${s.section||'destination'}|${s.label||''}|${s.url||''}`).join('\n');set(`sources[${locale}]`,sources);}
  const hero=pack.hero_image||{};set('image_origin',hero.image_origin||'ai_generated');for(const key of ['image_creator','image_source_url','image_license','image_license_url'])set(key,hero[key]||'');for(const locale of ['es','en','pt-BR']){set(`image_alt[${locale}]`,(hero.alt||{})[locale]||'');set(`image_caption[${locale}]`,(hero.caption||{})[locale]||'');}set('internal_research_json',JSON.stringify(pack.local_research||{schema_version:1},null,2));
  let cards=rows();while(cards.length<pack.places.length&&cards.length<40){addRow();cards=rows();}if(!keepImageFiles)imageInputs().forEach(el=>{el.value='';});
  cards.forEach((card,index)=>{const p=pack.places[index];const state=card.querySelector('[name$="[publication_status]"]');if(!p){const existingId=card.querySelector('[name$="[id]"]');if(existingId){card.dataset.emptyPlaceholder='0';if(state)state.value='archived';}else{card.dataset.emptyPlaceholder='1';if(state)state.value='draft';card.querySelectorAll('input:not([type=hidden]),textarea').forEach(el=>{if(el.type!=='file')el.value='';});const slug=card.querySelector('[name$="[slug]"]');if(slug)slug.value='';}return;}card.dataset.emptyPlaceholder='0';if(state)state.value='draft';const type=card.querySelector('[name$="[type]"]');if(type)type.value=p.type||'place';for(const locale of ['es','en','pt-BR'])for(const key of ['name','description','external_url','external_label']){const el=card.querySelector(`[name$="[${key}]"][name*="[${locale}]"]`)||card.querySelector(`[data-place-locale="${locale}"][data-place-key="${key}"]`);if(el)el.value=((p.translations||{})[locale]||{})[key]||'';}const image=p.image||{};for(const key of ['image_origin','image_creator','image_source_url','image_license','image_license_url']){const el=card.querySelector(`[name$="[${key}]"]`);if(el)el.value=image[key]||(key==='image_origin'?'ai_generated':'');}for(const locale of ['es','en','pt-BR'])for(const key of ['alt','caption']){const el=card.querySelector(`[name$="[${key}][${locale}]"]`);if(el)el.value=((image[key]||{})[locale])||'';}const slug=card.querySelector('[name$="[slug]"]');if(slug)slug.value=p.slug||'';const summary=card.querySelector('summary');if(summary)summary.textContent=((p.translations||{}).es||{}).name||`Atractivo ${index+1}`;});
 }
 file.addEventListener('change',async()=>{
  const selected=file.files&&file.files[0];if(!selected)return;
  if(form.elements.namedItem('id').value){status.textContent='El ZIP se usa para crear un destino nuevo. Abre «Crear destino» antes de importarlo.';file.value='';return;}
  if(selected.size>64*1024*1024){status.textContent='El ZIP debe pesar 64 MB o menos.';file.value='';return;}
  if(!confirm('Se reemplazará el contenido actual del formulario con el paquete. Los cambios aún no se guardarán y el destino quedará como borrador. ¿Continuar?')){file.value='';status.textContent='Importación cancelada.';return;}
  status.textContent='Validando textos e imágenes del ZIP…';
  try{
   const body=new FormData();body.append('csrf',form.elements.namedItem('csrf').value);body.append('package_zip',selected);
   const response=await fetch('paquete-destino.php',{method:'POST',body,credentials:'same-origin',headers:{Accept:'application/json'}});const result=await response.json();if(!response.ok)throw new Error(result.message||'No se pudo validar el ZIP.');
   const pack=result.manifest;const byPath=new Map(result.images.map(item=>[item.path,item]));
   const prepared=[];prepared.push([form.elements.namedItem('hero_upload'),pack.hero_image.file,byPath.get(pack.hero_image.file)]);
   pack.places.forEach((place,index)=>prepared.push([null,place.image.file,byPath.get(place.image.file),index]));
   const loaded=[];for(const item of prepared){if(!item[2])throw new Error(`El ZIP no incluye la imagen ${item[1]}.`);const responseImage=await fetch(item[2].url,{credentials:'same-origin'});if(!responseImage.ok)throw new Error(`No se pudo preparar la imagen ${item[1]}.`);const blob=await responseImage.blob();loaded.push({path:item[1],blob,index:item[3]});}
   imageInputs().forEach(input=>{if(input!==file&&input!==legacyFile)input.value='';});loadTextPackage(pack,true);tokenInput.value=result.token;
   const heroFile=new File([loaded[0].blob],loaded[0].path.split('/').pop(),{type:loaded[0].blob.type});let transfer=new DataTransfer();transfer.items.add(heroFile);form.elements.namedItem('hero_upload').files=transfer.files;
   loaded.slice(1).forEach(item=>{const input=form.querySelector(`[name="place_uploads[${item.index}]"]`);if(!input)throw new Error('No se encontró el campo de imagen de un atractivo.');const imageFile=new File([item.blob],item.path.split('/').pop(),{type:item.blob.type});const dt=new DataTransfer();dt.items.add(imageFile);input.files=dt.files;});
   clearPreviews();for(const item of loaded){const figure=document.createElement('figure'),img=document.createElement('img'),caption=document.createElement('figcaption');const objectUrl=URL.createObjectURL(item.blob);img.src=objectUrl;img.alt=item.path;img.dataset.objectUrl=objectUrl;caption.textContent=item.path;figure.append(img,caption);preview.append(figure);}
   status.textContent=`Paquete validado: destino, ${pack.places.length} atractivos y ${loaded.length} imágenes listos para revisar. Nada se guarda hasta que pulses «Guardar destino como borrador».`;
   document.querySelector('.destination-editor').scrollIntoView({behavior:'smooth',block:'start'});
  }catch(error){status.textContent=error.message||'No se pudo importar el paquete ZIP.';}finally{file.value='';}
 });
 legacyFile?.addEventListener('change',async()=>{const selected=legacyFile.files&&legacyFile.files[0];if(!selected)return;status.textContent='Leyendo paquete JSON anterior…';try{if(selected.size>2*1024*1024)throw new Error('El paquete JSON debe pesar 2 MB o menos.');const pack=JSON.parse(await selected.text());if(pack.schema_version!==1||!pack.destination||!Array.isArray(pack.places))throw new Error('El archivo no corresponde al paquete JSON v1.');if(pack.places.length>40)throw new Error('Un paquete puede incluir hasta 40 atractivos.');if(!confirm('Se reemplazarán los campos del formulario; tendrás que adjuntar las imágenes manualmente. Todavía no se guardará nada. ¿Continuar?')){status.textContent='Importación cancelada.';return;}tokenInput.value='';clearPreviews();loadTextPackage(pack,false);status.textContent=`Paquete JSON anterior importado: ${pack.places.length} atractivos. Adjunta las imágenes y guarda como borrador.`;document.querySelector('.destination-editor').scrollIntoView({behavior:'smooth',block:'start'});}catch(error){status.textContent=error.message||'No se pudo leer el paquete JSON.';}finally{legacyFile.value='';}});
})();
</script>
</main></body></html>
